import { IngestPipeline } from "@514labs/moose-lib";

// User Activity Event data model
// Fields mapped from CSV: event_id, event_ts, user_id, action, duration_ms
export interface UserActivityEvent {
  event_id: string;
  event_ts: Date;
  user_id: string;
  action: string;
  duration_ms: number; // Will default to 0 for null values
}

// Configure ingestion pipeline with ClickHouse table optimized for:
// 1. Activity counts per user over a date range (user_id + date filtering)
// 2. Total duration per action type (action grouping)
export const UserActivityEventPipeline = new IngestPipeline<UserActivityEvent>(
  "UserActivityEvent",
  {
    table: {
      // Order by user_id first for user-based queries, then event_ts for time range filters
      // This optimizes both query patterns efficiently
      orderByFields: ["user_id", "event_ts", "action"]
    },
    stream: true,
    ingestApi: true,
  }
);

